/* ===================== BÀI 38 · Latch, buffer và chip select ===================== */
/* Bài 38 · Latch, buffer và chip select (AMTS-EMB-002-M10-L02, X86-038) — sinh bởi tools/author/mpu8086/l38.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P38=[{"label": "Ví dụ: 74LS138 chia 1 MB thành 8 khối", "code": "; 74LS138: C B A = A19 A18 A17. Mỗi đầu ra Yi\n; tích cực trong một khối 128 KB = 20000h. In địa chỉ\n; đầu của 8 khối Y0…Y7.\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        XOR     BL, BL                  ; BL = i (0…7)\nkhoi:\n        MOV     AL, BL\n        SHL     AL, 1                   ; A19–A16 = i × 2\n        CALL    inNib                   ; chữ số hex đầu\n        MOV     CX, 4\nkhong:\n        MOV     DL, '0'                 ; A15–A0 = 0000h\n        MOV     AH, 02H\n        INT     21H\n        LOOP    khong\n        MOV     DL, ' '\n        INT     21H\n        INC     BL\n        CMP     BL, 8\n        JB      khoi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n\ninNib   PROC                            ; in 4 bit thấp của AL (0–F)\n        AND     AL, 0FH\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     inNib1\n        ADD     AL, 7\ninNib1:\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        RET\ninNib   ENDP\n        END     MAIN\n", "input": "", "note": "Mỗi đầu ra của 74LS138 ứng với một giá trị của A19 A18 A17, tức một khối 128 KB = 20000h. Chữ số hex đầu (A19–A16) của khối i là 2 × i, bốn chữ số sau luôn 0000. Xem màn hình in 00000 20000 … E0000. Đoán trước: trước lần gọi inNib thứ ba, AL bằng bao nhiêu? Đáp án 04h."}, {"label": "Ví dụ: tách địa chỉ thành các trường giải mã", "code": "; Tách địa chỉ F8123h thành các trường của bộ giải mã:\n; A19–A17 → đầu ra Yi của 74LS138, A16–A0 → trong khối\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nadrLo   DW      8123H                   ; A15–A0\nadrHi   DB      0FH                     ; A19–A16\ny       DB      ?                       ; số của đầu ra Y\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, adrHi\n        SHR     AL, 1                   ; bỏ A16: AL = A19 A18 A17\n        MOV     y, AL\n        MOV     DL, 'Y'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, y\n        ADD     DL, '0'\n        INT     21H                     ; in Y7\n        MOV     DL, ' '\n        INT     21H\n        MOV     AL, adrHi\n        AND     AL, 1                   ; A16: bit cao nhất trong khối\n        CALL    inNib\n        MOV     BX, adrLo\n        CALL    inHex4                  ; A15–A0\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n\ninHex4  PROC                            ; in BX ra 4 chữ số hex\n        MOV     CH, 4\nlap4:\n        MOV     CL, 4\n        ROL     BX, CL\n        MOV     AL, BL\n        CALL    inNib\n        DEC     CH\n        JNZ     lap4\n        RET\ninHex4  ENDP\n\ninNib   PROC                            ; in 4 bit thấp của AL (0–F)\n        AND     AL, 0FH\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     inNib1\n        ADD     AL, 7\ninNib1:\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        RET\ninNib   ENDP\n        END     MAIN\n", "input": "", "note": "SHR AL, 1 bỏ A16 khỏi chữ số A19–A16 = Fh, còn A19 A18 A17 = 111 = 7: chip ở đầu ra Y7. Phần còn lại A16–A0 = 1 8123h là địa chỉ trong khối 128 KB. MOV DL, y tốn 8 + EA 6 = 14 chu kỳ. Đoán trước: sau SHR AL, 1, AL bằng bao nhiêu? Đáp án 07h."}, {"label": "Ví dụ: giải mã đầy đủ cho EPROM 32 KB", "code": "; Giải mã đầy đủ cho EPROM 32 KB ở F8000h–FFFFFh:\n; CS tích cực khi A19…A15 = 11111. Kiểm 5 địa chỉ,\n; in C (chọn) hoặc . (không chọn).\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\n; mỗi địa chỉ 3 byte: A15–A0 (word) rồi A19–A16\nbang    DW      8000H\n        DB      0FH                     ; F8000h\n        DW      0FFF0H\n        DB      0FH                     ; FFFF0h\n        DW      8000H\n        DB      07H                     ; 78000h\n        DW      0000H\n        DB      0FH                     ; F0000h\n        DW      0FFFFH\n        DB      0FH                     ; FFFFFh\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET bang\n        MOV     CX, 5\nkiem:\n        MOV     DL, '.'\n        CMP     BYTE PTR [SI+2], 0FH    ; A19–A16 = 1111?\n        JNE     inRa\n        TEST    WORD PTR [SI], 8000H    ; A15 = 1?\n        JZ      inRa\n        MOV     DL, 'C'\ninRa:\n        MOV     AH, 02H\n        INT     21H\n        ADD     SI, 3\n        LOOP    kiem\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "EPROM 32 KB ở F8000h–FFFFFh: chọn khi A19–A16 = 1111 (CMP byte cao) và A15 = 1 (TEST word thấp với 8000h). 78000h có A19 = 0, F0000h có A15 = 0 nên không chọn: màn hình CC..C. CMP bộ nhớ với số tức thời 10 + EA 9 = 19 chu kỳ. Đoán trước: với địa chỉ thứ tư (F0000h), JZ có nhảy không? Đáp án có (A15 = 0)."}, {"label": "Bẫy: giải mã một phần tạo vùng alias", "code": "; Giải mã một phần: RAM 8 KB chọn chỉ bằng A19 = 0.\n; Hai địa chỉ khác nhau rơi vào cùng một ô của RAM.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na1Lo    DW      1234H                   ; 01234h\na2Lo    DW      0F234H                  ; 7F234h (A19 = 0 → RAM vẫn chọn)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, a1Lo\n        AND     BX, 1FFFH               ; RAM 8 KB chỉ nhận A12–A0\n        CALL    inHex4\n        MOV     DL, ' '\n        MOV     AH, 02H\n        INT     21H\n        MOV     BX, a2Lo\n        AND     BX, 1FFFH\n        CALL    inHex4                  ; cùng 1234: hai địa chỉ, một ô\n        MOV     DL, ' '\n        MOV     AH, 02H\n        INT     21H\n        MOV     CL, 6                   ; 6 bit bỏ qua: A18–A13\n        MOV     AL, 1\n        SHL     AL, CL                  ; 2^6 = 64 vùng alias\n        AAM                             ; AH = 6, AL = 4 (hai chữ số)\n        MOV     BX, AX\n        MOV     DL, BH\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, BL\n        ADD     DL, '0'\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n\ninHex4  PROC                            ; in BX ra 4 chữ số hex\n        MOV     CH, 4\nlap4:\n        MOV     CL, 4\n        ROL     BX, CL\n        MOV     AL, BL\n        CALL    inNib\n        DEC     CH\n        JNZ     lap4\n        RET\ninHex4  ENDP\n\ninNib   PROC                            ; in 4 bit thấp của AL (0–F)\n        AND     AL, 0FH\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     inNib1\n        ADD     AL, 7\ninNib1:\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        RET\ninNib   ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: RAM 8 KB chỉ chọn bằng A19 = 0, sáu bit A18–A13 bị bỏ. 01234h và 7F234h cho cùng địa chỉ trong chip 1234h: hai địa chỉ, một ô nhớ. Số vùng 2^6 = 64 (AAM tách 64 thành 6 và 4 để in). Sửa nếu cần dùng các khối khác: đưa thêm A18–A13 vào giải mã. Đoán trước: AND BX, 1FFFh với BX = F234h cho bao nhiêu? Đáp án 1234h."}, {"label": "Lỗi: hai RAM cùng được chọn ở một khối", "code": "; Phương trình chọn chip chồng nhau:\n;   RAM 1: A19 = 0 và A15 = 0;  RAM 2: A19 = 0 và A14 = 1\n; Duyệt 8 khối 16 KB đầu (A16 A15 A14 = 000…111),\n; in 1, 2, X (cả hai: xung đột) hoặc . (không chip nào).\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        XOR     BL, BL                  ; số khối: bit 1 = A15, bit 0 = A14\nkhoi:\n        XOR     BH, BH                  ; BH: bit 0 = RAM 1, bit 1 = RAM 2\n        TEST    BL, 2                   ; A15\n        JNZ     xetR2\n        OR      BH, 1                   ; A15 = 0 → RAM 1 chọn\nxetR2:\n        TEST    BL, 1                   ; A14\n        JZ      inKq\n        OR      BH, 2                   ; A14 = 1 → RAM 2 chọn\ninKq:\n        MOV     DL, '.'\n        CMP     BH, 1\n        JB      inRa\n        MOV     DL, '1'\n        JE      inRa\n        MOV     DL, '2'\n        CMP     BH, 2\n        JE      inRa\n        MOV     DL, 'X'                 ; cả hai cùng chọn\ninRa:\n        MOV     AH, 02H\n        INT     21H\n        INC     BL\n        CMP     BL, 8\n        JB      khoi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: RAM 1 (A19 = 0, A15 = 0) và RAM 2 (A19 = 0, A14 = 1) không khác nhau ở bit nào, nên khối có A15 = 0, A14 = 1 chọn cả hai (X). Kết quả 1X.21X.2 lặp lại mỗi 64 KB vì A16 không được giải mã. Sửa: thêm A15 = 1 vào phương trình RAM 2 (mẫu “Sửa” của Công cụ 38.1). Đoán trước: khối thứ hai (BL = 1) in gì? Đáp án X."}];
const sim38=makeX86Sim(document.getElementById("x86-l38"),{id:"s38",presets:P38,file:"BAI38.ASM"});
makeX86Ex(document.getElementById("ex-l38"),sim38,[{"t": "Đầu ra nào của 74LS138", "d": "Bộ giải mã 74LS138 nhận C B A = A19 A18 A17 (G1 = 1, G2A = G2B = 0), nên đầu ra Yn tích cực khi A19 A18 A17 = n. Đọc một địa chỉ vật lý 5 chữ số hex (0–9, A–F in hoa) bằng INT 21h hàm 08h. Ghi n vào biến byte y và in Yn (ví dụ địa chỉ 9ABCD → Y4). Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: 74LS138 với C B A = A19 A18 A17.\n; Đọc địa chỉ 5 chữ số hex, in Yn (n = đầu ra tích cực),\n; ghi n vào biến y.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ny       DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; chữ số đầu: A19–A16\n        INT     21H\n; TODO: đổi ra số, lấy A19 A18 A17, ghi y\n        MOV     y, 0\n        MOV     DL, 'Y'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, y\n        ADD     DL, '0'\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "9ABCD", "out": "Y4", "mem": [{"at": "y", "bytes": [4]}]}, {"in": "00000", "out": "Y0", "mem": [{"at": "y", "bytes": [0]}]}, {"in": "1FFFF", "out": "Y0", "mem": [{"at": "y", "bytes": [0]}]}, {"in": "20000", "out": "Y1", "mem": [{"at": "y", "bytes": [1]}]}, {"in": "BFFFF", "out": "Y5", "mem": [{"at": "y", "bytes": [5]}]}, {"in": "E0000", "out": "Y7", "mem": [{"at": "y", "bytes": [7]}]}, {"in": "FFFF0", "out": "Y7", "mem": [{"at": "y", "bytes": [7]}]}]}, {"t": "Alias của RAM giải mã một phần", "d": "RAM 8 KB được chọn khi A19 = 0 và A15 = 0; các bit A18–A16, A14–A13 không được giải mã. Đọc một địa chỉ 5 chữ số hex (thủ tục docHex có sẵn). Nếu RAM được chọn: ghi chon = 1, ghi địa chỉ trong chip (A12–A0) vào biến word off và in RAM rồi off ra 4 chữ số hex (ví dụ 61234 → RAM 1234). Nếu không: chon = 0, off = 0, in NO. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: RAM 8 KB, giải mã một phần: chọn khi\n; A19 = 0 và A15 = 0. Đọc địa chỉ 5 chữ số hex.\n; Được chọn: chon = 1, off = địa chỉ trong chip, in\n; RAM xxxx. Không chọn: chon = 0, off = 0, in NO.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchon    DB      ?\noff     DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        CALL    docHex                  ; AL = A19–A16\n; TODO: đọc tiếp 4 chữ số, xét A19, A15, tính off\n        MOV     chon, 0\n        MOV     off, 0\n        MOV     DL, 'N'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, 'O'\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n\ndocHex  PROC                            ; đọc 1 chữ số hex vào AL (0–15)\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        CMP     AL, 9\n        JBE     docHex1\n        SUB     AL, 7\ndocHex1:\n        RET\ndocHex  ENDP\n\ninHex4  PROC                            ; in BX ra 4 chữ số hex\n        MOV     CH, 4\nlap4:\n        MOV     CL, 4\n        ROL     BX, CL\n        MOV     AL, BL\n        CALL    inNib\n        DEC     CH\n        JNZ     lap4\n        RET\ninHex4  ENDP\n\ninNib   PROC                            ; in 4 bit thấp của AL (0–F)\n        AND     AL, 0FH\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     inNib1\n        ADD     AL, 7\ninNib1:\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        RET\ninNib   ENDP\n        END     MAIN\n", "tests": [{"in": "61234", "out": "RAM 1234", "mem": [{"at": "chon", "bytes": [1]}, {"at": "off", "word": 4660}]}, {"in": "01234", "out": "RAM 1234", "mem": [{"at": "chon", "bytes": [1]}, {"at": "off", "word": 4660}]}, {"in": "6F234", "out": "NO", "mem": [{"at": "chon", "bytes": [0]}, {"at": "off", "word": 0}]}, {"in": "80000", "out": "NO", "mem": [{"at": "chon", "bytes": [0]}, {"at": "off", "word": 0}]}, {"in": "7FFFF", "out": "NO", "mem": [{"at": "chon", "bytes": [0]}, {"at": "off", "word": 0}]}, {"in": "77FFF", "out": "RAM 1FFF", "mem": [{"at": "chon", "bytes": [1]}, {"at": "off", "word": 8191}]}, {"in": "00000", "out": "RAM 0000", "mem": [{"at": "chon", "bytes": [1]}, {"at": "off", "word": 0}]}]}, {"t": "Bộ giải mã bằng bảng tra nhanh hơn", "d": "Mô phỏng một bộ giải mã dùng PROM: mỗi khối 64 KB (chữ số hex đầu, A19–A16) cho một ký tự: 0–3 → R (RAM), A–B → V (bộ nhớ màn hình), E–F → O (EPROM), các khối khác → . (trống). Đọc chữ số đó bằng INT 21h hàm 08h (0–9 hoặc A–F in hoa), ghi ký tự vào biến chip và in ra. Code mẫu đúng nhưng dùng chuỗi so sánh. Viết lại để đạt cả giới hạn chu kỳ và byte mã. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: bộ giải mã bằng bảng (như PROM giải mã)\n; Khối 64 KB theo A19–A16: 0–3 RAM (R), A–B màn hình\n; (V), E–F EPROM (O), còn lại trống (.). Đọc 1 chữ số\n; hex, ghi ký tự vào chip và in ra. Bản này đúng nhưng\n; dùng chuỗi so sánh nên chậm. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchip    DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'                 ; đổi chữ số hex ra số\n        CMP     AL, 9\n        JBE     so\n        SUB     AL, 7\nso:\n        MOV     DL, 'R'\n        CMP     AL, 3\n        JBE     ghi\n        MOV     DL, 'V'\n        CMP     AL, 0AH\n        JE      ghi\n        CMP     AL, 0BH\n        JE      ghi\n        MOV     DL, 'O'\n        CMP     AL, 0EH\n        JAE     ghi\n        MOV     DL, '.'\nghi:\n        MOV     chip, DL\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "F", "out": "O", "mem": [{"at": "chip", "bytes": [79]}]}, {"in": "0", "out": "R", "mem": [{"at": "chip", "bytes": [82]}]}, {"in": "3", "out": "R", "mem": [{"at": "chip", "bytes": [82]}]}, {"in": "A", "out": "V", "mem": [{"at": "chip", "bytes": [86]}]}, {"in": "4", "out": ".", "mem": [{"at": "chip", "bytes": [46]}]}, {"in": "9", "out": ".", "mem": [{"at": "chip", "bytes": [46]}]}, {"in": "B", "out": "V", "mem": [{"at": "chip", "bytes": [86]}]}, {"in": "D", "out": ".", "mem": [{"at": "chip", "bytes": [46]}]}], "perf": {"cycles": 215, "bytes": 30}}]);
makeX86Decode(document.getElementById("dec-l38"),{"designs": [{"label": "74LS138: C B A = A19 A18 A17, ba chip trên Y0, Y1, Y7", "note": "Mỗi đầu ra Yi của 74LS138 tích cực ở một khối 128 KB. RAM 0 trên Y0, RAM 1 trên Y1, EPROM 128 KB trên Y7.", "chips": [{"id": "ram0", "name": "RAM 0 (Y0)", "kind": "RAM", "size": 131072, "cs": {"19": 0, "18": 0, "17": 0}}, {"id": "ram1", "name": "RAM 1 (Y1)", "kind": "RAM", "size": 131072, "cs": {"19": 0, "18": 0, "17": 1}}, {"id": "rom", "name": "EPROM (Y7)", "kind": "ROM", "size": 131072, "cs": {"19": 1, "18": 1, "17": 1}}]}, {"label": "Giải mã một phần: chỉ dùng A19", "note": "RAM 8 KB chọn khi A19 = 0, EPROM 8 KB khi A19 = 1; A18–A13 bị bỏ qua nên mỗi chip lặp lại 64 lần.", "chips": [{"id": "ram", "name": "RAM 8 KB", "kind": "RAM", "size": 8192, "cs": {"19": 0}}, {"id": "rom", "name": "EPROM 8 KB", "kind": "ROM", "size": 8192, "cs": {"19": 1}}]}, {"label": "Lỗi: hai RAM cùng được chọn", "note": "RAM 1 chọn khi A19 = 0 và A15 = 0, RAM 2 khi A19 = 0 và A14 = 1. Ở 04000h cả hai đều được chọn.", "chips": [{"id": "r1", "name": "RAM 1 16 KB", "kind": "RAM", "size": 16384, "cs": {"19": 0, "15": 0}}, {"id": "r2", "name": "RAM 2 16 KB", "kind": "RAM", "size": 16384, "cs": {"19": 0, "14": 1}}, {"id": "rom", "name": "EPROM 16 KB", "kind": "ROM", "size": 16384, "cs": {"19": 1}}]}, {"label": "Sửa: RAM 2 thêm điều kiện A15 = 1", "note": "Thêm A15 vào phương trình của RAM 2 (A15 = 1): hai RAM khác nhau ở A15 nên không bao giờ cùng được chọn.", "chips": [{"id": "r1", "name": "RAM 1 16 KB", "kind": "RAM", "size": 16384, "cs": {"19": 0, "15": 0}}, {"id": "r2", "name": "RAM 2 16 KB", "kind": "RAM", "size": 16384, "cs": {"19": 0, "15": 1, "14": 1}}, {"id": "rom", "name": "EPROM 16 KB", "kind": "ROM", "size": 16384, "cs": {"19": 1}}]}]});

makeQuiz("quiz38","score38",[{"q": "Vì sao bus địa chỉ của bộ nhớ phải lấy từ đầu ra của chốt (nối ALE) chứ không nối thẳng vào chân AD15–AD0 của 8086?", "o": ["AD15–AD0 chỉ có 16 bit nên không đủ cho địa chỉ 20 bit", "AD15–AD0 chỉ mang địa chỉ trong T1, sau đó mang dữ liệu", "Chốt đổi địa chỉ logic đoạn:độ lệch thành địa chỉ vật lý", "ALE chỉ bật khi đọc ROM nên RAM không cần chốt"], "a": 1, "e": "Các chân dồn kênh mang địa chỉ trong T1 rồi chuyển sang dữ liệu; chốt giữ địa chỉ suốt chu kỳ bus. Địa chỉ vật lý do CPU tính, chốt không tính gì; A19–A16 cũng được chốt nhưng đó không phải lý do chính."}, {"q": "74LS138 có C B A = A19 A18 A17, G1 = M/IO, G2A = G2B = 0. Chương trình chạy <code>MOV DX, 0E000h<\/code> rồi <code>OUT DX, AL<\/code>. Đầu ra nào bằng 0 trong chu kỳ bus đó?", "o": ["Y7, vì A19 A18 A17 của E000h là 111", "Y0, vì cổng I/O chỉ có 16 bit nên A19–A16 = 0", "Không đầu ra nào: M/IO = 0 nên G1 cấm bộ giải mã", "Y7 và Y0 cùng bằng 0 trong một chu kỳ bus"], "a": 2, "e": "Chu kỳ ghi cổng có M/IO = 0, mà G1 phải bằng 1 thì 74LS138 mới hoạt động, nên cả 8 đầu ra bằng 1. Nếu nối G1 cố định 1 thì sẽ có Y0 (A19–A16 = 0 trong chu kỳ I/O) chọn nhầm RAM."}, {"q": "RAM 16 KB được chọn chỉ bằng điều kiện A19 = 0 (không dùng bit nào khác). RAM xuất hiện ở bao nhiêu vùng địa chỉ?", "o": ["64 vùng (bỏ 6 bit A18–A13)", "16 vùng (bỏ 4 bit A18–A15)", "2 vùng (A19 chia đôi bộ nhớ)", "32 vùng (bỏ 5 bit A18–A14)"], "a": 3, "e": "RAM 16 KB dùng A13–A0 (k = 14). Các bit cao A19…A14 có 6 bit, A19 đã dùng, còn A18–A14 là 5 bit bỏ qua: 2^5 = 32 vùng. 64 vùng là đáp án cho RAM 8 KB."}, {"q": "Đoạn code sau tính địa chỉ trong chip của RAM 8 KB giải mã một phần. Với địa chỉ 5F234h, BX bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     BX, 0F234H              ; A15–A0 của 5F234h\n        AND     BX, 1FFFH<\/pre>", "o": ["F234h", "0234h", "1234h", "3234h"], "a": 2, "e": "RAM 8 KB nhận 13 bit A12–A0; F234h AND 1FFFh = 1234h. 3234h là kết quả nếu giữ thêm A13 (AND 3FFFh, RAM 16 KB)."}, {"q": "RAM A chọn khi A19 = 0 và A16 = 0; RAM B chọn khi A19 = 0 và A15 = 1. Thiết kế này có xung đột không?", "o": ["Có, ví dụ ở 08000h cả hai cùng được chọn", "Không, vì hai phương trình dùng hai bit khác nhau", "Không, vì A19 = 0 giống nhau nên chỉ một chip chạy", "Có, nhưng chỉ khi CPU ghi, đọc thì không sao"], "a": 0, "e": "Không có bit nào mà một chip đòi 0, chip kia đòi 1; đặt A19 = 0, A16 = 0, A15 = 1 được 08000h chọn cả hai. Dùng hai bit khác nhau không đủ để loại trừ; xung đột khi đọc mới là nguy hiểm nhất."}]);

